"""Deterministic lineage helpers for R6 S5 bounded-authorization preparation v1."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any, Mapping

from src.ops.canonical_r6_s5_bounded_authorization_preparation_v1.constants_v1 import (
    CANONICAL_SERIALIZATION_VERSION,
    CONTRACT_CONFIG_REL_PATH,
)
from src.ops.canonical_r6_s5_bounded_authorization_preparation_v1.models_v1 import (
    R6S5BoundedAuthorizationPreparationError,
)


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def contract_config_path(root: Path | None = None) -> Path:
    return (root or repo_root()) / CONTRACT_CONFIG_REL_PATH


def _jsonable(value: Any) -> Any:
    if isinstance(value, dict):
        return {str(key): _jsonable(item) for key, item in value.items()}
    if isinstance(value, Mapping):
        return {str(key): _jsonable(item) for key, item in value.items()}
    if isinstance(value, (tuple, list)):
        return [_jsonable(item) for item in value]
    return value


def canonical_dumps(payload: Mapping[str, Any]) -> str:
    return json.dumps(
        _jsonable(payload),
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    )


def sha256_hex(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def digest_mapping(payload: Mapping[str, Any]) -> str:
    return sha256_hex(canonical_dumps(payload))


def envelope_digest(*, kind: str, payload: Mapping[str, Any]) -> str:
    return digest_mapping(
        {
            "canonical_serialization_version": CANONICAL_SERIALIZATION_VERSION,
            "kind": kind,
            "payload": dict(payload),
        }
    )


def load_layer_config_v1(root: Path | None = None) -> dict[str, Any]:
    path = contract_config_path(root)
    if not path.is_file():
        raise R6S5BoundedAuthorizationPreparationError(f"contract_config_missing:{path}")
    payload = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(payload, dict):
        raise R6S5BoundedAuthorizationPreparationError("contract_config_not_object")
    return payload

"""R6 S5 bounded-authorization preparation identity.

Dedicated preparation identity plane. Package-N SHA256 live-owner join
remains a distinct plane and is not consumed here. MD5-12 is forbidden.
"""

from __future__ import annotations

from types import MappingProxyType
from typing import Any, Mapping

from src.ops.canonical_r6_s5_bounded_authorization_preparation_v1.constants_v1 import (
    CANONICAL_SERIALIZATION_VERSION,
    CAPABILITY_ID,
    CONTRACT_VERSION,
    IDENTITY_JOIN_KEY,
    IDENTITY_PLANE,
    MD5_12_FORBIDDEN,
    PACKAGE_N_IS_NOT_MF_IDENTITY,
    PACKAGE_N_LIVE_OWNER_JOIN_NOT_USED,
)
from src.ops.canonical_r6_s5_bounded_authorization_preparation_v1.lineage_v1 import (
    canonical_dumps,
    digest_mapping,
    sha256_hex,
)
from src.ops.canonical_r6_s5_bounded_authorization_preparation_v1.models_v1 import (
    R6S5BoundedAuthorizationPreparationError,
)


def _reject(message: str) -> None:
    raise R6S5BoundedAuthorizationPreparationError(message)


def identity_payload_v1(*, preparation_digest: str) -> Mapping[str, Any]:
    if IDENTITY_JOIN_KEY != "sha256":
        _reject("identity_join_key_must_be_sha256")
    if MD5_12_FORBIDDEN is not True:
        _reject("md5_12_must_remain_forbidden")
    if PACKAGE_N_LIVE_OWNER_JOIN_NOT_USED is not True:
        _reject("package_n_live_owner_join_must_remain_unused")
    if "md5" in preparation_digest.lower():
        _reject("md5_digest_forbidden")
    payload = {
        "capability_id": CAPABILITY_ID,
        "canonical_serialization_version": CANONICAL_SERIALIZATION_VERSION,
        "contract_version": CONTRACT_VERSION,
        "identity_join_key": IDENTITY_JOIN_KEY,
        "identity_plane": IDENTITY_PLANE,
        "md5_12_forbidden": MD5_12_FORBIDDEN,
        "package_n_is_not_mf_identity": PACKAGE_N_IS_NOT_MF_IDENTITY,
        "package_n_live_owner_join_not_used": PACKAGE_N_LIVE_OWNER_JOIN_NOT_USED,
        "preparation_digest": preparation_digest,
        "preparation_is_not_authorization": True,
    }
    return MappingProxyType(payload)


def build_preparation_identity_v1(*, preparation_digest: str) -> Mapping[str, Any]:
    payload = identity_payload_v1(preparation_digest=preparation_digest)
    identity_id = sha256_hex(canonical_dumps(payload))
    if len(identity_id) != 64:
        _reject("identity_id_not_sha256_hex")
    return MappingProxyType(
        {
            "experiment_identity_id": identity_id,
            "identity_digest": digest_mapping(payload),
            "identity_payload": dict(payload),
            "lanes": {
                "CONTENT_HASH": preparation_digest,
                "IDENTITY": identity_id,
                "PREPARATION": identity_id,
            },
        }
    )

